/* Named function lookup and invocation preserve roots and output across allocation failures. */
#define main existing_allocation_main
#include "execution_services_allocation.cpp"
#undef main
#include "flashvm/function.h"
#include "../src/core/runtime.hpp"
static FVM_Result body(FVM_Context *,const FVM_ScriptFrame *,FVM_Value *out,void *){fvm_value_number(out,42);return FVM_OK;}
int main(){FVM_Config cfg;FVM_Runtime *rt=0;FVM_Context *c=0;FVM_Object *receiver=0,*fn=0;assert(fvm_config_init(&cfg)==FVM_OK && fvm_runtime_create(&cfg,&rt)==FVM_OK && fvm_context_create(rt,&c)==FVM_OK);unsigned char swf[]={'F','W','S',8,16,0,0,0,8,0,0,12,1,0,0,0};const unsigned char code[]={0};assert(fvm_load_memory(c,swf,sizeof(swf))==FVM_OK && fvm_standard_install(c)==FVM_OK && fvm_object_create(c,&receiver)==FVM_OK && fvm_gc_pin(c,receiver)==FVM_OK && fvm_function_create_avm1(c,code,sizeof(code),0,0,0,&fn)==FVM_OK && fvm_function_set_body(c,fn,body,0,0)==FVM_OK);FVM_Value name,value,out;fvm_value_undefined(&value);value.type=FVM_VALUE_OBJECT;value.object=fn;assert(fvm_object_set(c,receiver,"cell",&value)==FVM_OK);fvm_value_string(&name,"cell");bool success=false;unsigned failures=0;for(long boundary=0;boundary<2000 && !success;++boundary){FVM_GCRootFrame *roots=c->gc_frames;fvm_value_number(&out,99);allowance=boundary;FVM_Result r=fvm_exec_invoke_member(c,receiver,&name,0,0,&out);allowance=-1;assert(c->gc_frames==roots && !c->calling_function && !c->calling_owner);if(r==FVM_OK){assert(out.number==42);success=true;}else{assert(r==FVM_OUT_OF_MEMORY && out.type==FVM_VALUE_NUMBER && out.number==99);++failures;}assert(fvm_gc_collect(c,0)==FVM_OK);}assert(success && failures);fvm_context_destroy(c);fvm_runtime_destroy(rt);return 0;}
